CREATE TABLE loan ( 
        id INT AUTO_INCREMENT PRIMARY KEY,
        timestamp TEXT,
        company_id INTEGER,
        asset_id INTEGER,
        amount INTEGER,
        interest_rate INTEGER,
        ongoing TINYINT(1) DEFAULT TRUE,
        FOREIGN KEY (company_id) REFERENCES company (id),
        FOREIGN KEY (asset_id) REFERENCES asset (id)
        );
