CREATE TABLE event (
        id INT AUTO_INCREMENT PRIMARY KEY, 
        status_id INTEGER,
        event_title TEXT,
        story_type TEXT,
        duration INTEGER,
        severity INTEGER,
        target TINYINT(1) DEFAULT FALSE,
        price INTEGER,
        FOREIGN KEY (status_id) REFERENCES status (id)
        );
